# Expected values generated by test/scipy/gen_core_expected.py (scipy 1.18.1).
import numpy as np
import scipy.linalg as sl

def close(x, ref, rtol: float = 1e-12, atol: float = 1e-13) -> bool:
    a = np.asarray(x)
    r = np.asarray(ref)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

def mat_a():
    return np.array([[4., 1., 2.], [1., 3., .5], [2., .5, 5.]])
def mat_b():
    return np.array([[2., .3, .1], [.3, 1.5, .2], [.1, .2, 1.]])

def bp_data():
    bp = np.empty((40, 8))
    for i in range(40):
        for j in range(8):
            bp[i, j] = ((i * 7 + j * 13) % 17) / 3.0 + 0.25 * j + (i % 5) * 0.1
    y = np.array([i % 2 for i in range(40)])
    return bp, y

