@test
def test_eigh():
    A, B = mat_a(), mat_b()
    w, v = sl.eigh(A)
    assert close(w, eigh_w)
    assert close(v, eigh_v, 1e-10, 1e-12)
    w2, v2 = sl.eigh(A, B)
    assert close(w2, geigh_w)
    assert close(v2, geigh_v, 1e-10, 1e-12)
    assert close(sl.eigh(A, B, lower=False, eigvals_only=True), geigh_U_w)
    assert close(sl.eigh(A, B, type=2, eigvals_only=True), geigh_t2)
    assert close(sl.eigh(A, B, type=3, eigvals_only=True), geigh_t3)
    assert close(sl.eigh(A, B, subset_by_index=[1, 2], eigvals_only=True), geigh_sub)
    ws, vs = sl.eigh(A, subset_by_index=[0, 0])
    assert close(ws, eigh_sub_w)
    assert close(vs, eigh_sub_v, 1e-10, 1e-12)
    assert close(sl.eigh(A, subset_by_value=[2.5, 10.0], eigvals_only=True), eigh_val)
    assert close(sl.eigvalsh(A, B), eigvalsh_ab)
    for d in ('ev', 'evd', 'evx'):
        assert close(sl.eigh(A, driver=d, eigvals_only=True), eigh_w)
    for d in ('gv', 'gvx'):
        assert close(sl.eigh(A, B, driver=d, eigvals_only=True), eigvalsh_ab)
    try:
        sl.eigh(A, B, driver='evr')
        assert False
    except ValueError:
        pass
    try:
        sl.eigh(A, -B)
        assert False
    except sl.LinAlgError:
        pass
test_eigh()

@test
def test_acceptance_eigh():
    bp, y = bp_data()
    X0 = bp[y == 0]
    X1 = bp[y == 1]
    C0 = X0.T @ X0 / 20.0 + np.eye(8)
    C1 = X1.T @ X1 / 20.0 + np.eye(8)
    w = sl.eigh(C0, C0 + C1, eigvals_only=True)
    assert close(w, acc_w, 1e-12, 1e-14)
test_acceptance_eigh()

