@test
def test_basic():
    A, G = mat_a(), mat_g()
    b = np.array([1., 2., 3.])
    assert close(sl.inv(G), inv_g)
    assert close(sl.inv(A), inv_a)
    assert close(sl.solve(G, b), solve_g)
    assert close(sl.solve(A, b, assume_a='pos'), solve_pos)
    assert close(sl.solve(A, b, assume_a='sym'), solve_sym)
    assert close(sl.det(G), det_g)
    assert close(sl.cholesky(A), chol_a)
    assert close(sl.cholesky(A, lower=True), chol_al)
    p, l, u = sl.lu(G)
    assert close(p, lu_p) and close(l, lu_l) and close(u, lu_u)
    q, r = sl.qr(G)
    assert close(q, qr_q) and close(r, qr_r)
    assert close(sl.svdvals(G), svdvals_g)
    assert close(sl.pinv(G), pinv_g)
    assert close(sl.pinvh(A), pinvh_a, 1e-12, 1e-15)
    assert close(sl.lstsq(G, b)[0], lstsq_g)
    assert close(sl.solve_triangular(np.triu(G), b), solve_tri)
    assert close(sl.cho_solve(sl.cho_factor(A), b), cho_solve)
    assert close(sl.lu_solve(sl.lu_factor(G), b), lu_solve)
    assert close(sl.toeplitz([1., 2., 3.], [1., 5.]), toep)
test_basic()

@test
def test_matfuncs():
    A, G = mat_a(), mat_g()
    # expm agrees to rounding of the Pade/solve path (~1e-14 rel)
    assert close(sl.expm(G * 0.3), expm_small)
    assert close(sl.expm(G), expm_g)
    # norm ~ 2e1: scipy's C kernel and the Al-Mohy-Higham Python path
    # (scipy.sparse.linalg.expm) themselves differ by 1.7e-12 rel here
    assert close(sl.expm(G * 3.0), expm_big, 5e-12, 0.0)
    assert close(sl.expm(np.triu(G)), expm_tri)
    # Schur-based functions: different (but equally accurate) recurrences
    # from scipy's blocked/Pade code, agree to ~1e-14 abs
    assert close(sl.sqrtm(A), sqrtm_a, 1e-12, 1e-14)
    assert close(sl.logm(A), logm_a, 1e-12, 1e-14)
    assert close(sl.logm(G @ G.T + np.eye(3)), logm_g2, 1e-12, 1e-14)
    assert close(sl.fractional_matrix_power(A, 0.5), fmp_a, 1e-12, 1e-14)
    assert close(sl.fractional_matrix_power(A, -0.3), fmp_a3, 1e-12, 1e-14)
test_matfuncs()

