@test
def test_batched():
    A, B, G = mat_a(), mat_b(), mat_g()
    S = np.stack((A, A * 2.0))
    T3 = np.stack((G, G.T))
    assert close(sl.eigh(S, B, eigvals_only=True), b_geigh)
    w, v = sl.eigh(S)
    assert close(w, b_eigh_w)
    assert close(v, b_eigh_v, 1e-10, 1e-12)
    assert close(sl.det(T3), b_det)
    assert close(sl.inv(T3), b_inv)
    assert close(sl.solve(T3, np.array([1., 2., 3.])), b_solve)
    assert close(sl.cholesky(S), b_chol)
    assert close(sl.svd(T3, compute_uv=False), b_svals)
    assert close(sl.expm(T3 * 0.2), b_expm)
    assert close(sl.logm(S), b_logm, 1e-12, 1e-14)
    assert close(sl.sqrtm(S), b_sqrtm, 1e-12, 1e-14)
test_batched()

@test
def test_geneig_qrpivot():
    B, G = mat_b(), mat_g()
    w, vr = sl.eig(G, B)
    wr = np.array([x.real for x in w])
    vre = np.array([[x.real for x in row] for row in vr.tolist()])
    assert close(wr, ge_w)
    assert close(vre, ge_v, 1e-10, 1e-12)
    wi = sl.eigvals(np.array([[0., -1.], [1., 0.]]), np.array([[0., 1.], [1., 1.]]))
    assert close(np.array([x.real for x in wi]), ge_vals_im)
    q, r, p = sl.qr(G, pivoting=True)
    assert close(q, qp_q)
    assert close(r, qp_r)
    assert close(p.astype(float), qp_p)
test_geneig_qrpivot()
